// Works for both triggers: Gmail (after PDF extraction) and the test webhook.
const item = $input.item.json;
let meta = {};
try { meta = $('Gmail Trigger').item.json; } catch (e) { meta = {}; }
const body = item.body || item;

const fromValue = meta.from && meta.from.value ? meta.from.value[0] : null;
const candidateEmail = fromValue ? fromValue.address : body.candidate_email;
const candidateName = (fromValue && fromValue.name) || body.candidate_name || (candidateEmail ? candidateEmail.split('@')[0] : 'Candidate');
const resumeText = (item.text || body.resume_text || meta.text || '').trim();

if (!candidateEmail) throw new Error('No candidate email found in trigger payload');
if (!resumeText) throw new Error('No resume text found (attach a PDF resume or send resume_text)');

let resumeFilename = body.resume_filename || 'resume.pdf';
try { resumeFilename = $('Gmail Trigger').item.binary.attachment_0.fileName; } catch (e) {}

return [{ json: {
  candidate_name: candidateName,
  candidate_email: candidateEmail,
  resume_filename: resumeFilename,
  resume_text: resumeText,
  job_id: body.job_id || 'python-ml-developer-001'
}}];

// If Gemini fails we throw, so the workflow errors instead of emailing a false rejection.
const response = $input.item.json;
const rawText = response.candidates[0].content.parts[0].text
  .replace(/```json/g, '').replace(/```/g, '').trim();
const evalData = JSON.parse(rawText);
const candidate = $('Normalize Candidate Data').item.json;

return [{ json: {
  email: candidate.candidate_email,
  name: candidate.candidate_name,
  job_id: candidate.job_id,
  resume_score: parseInt(evalData.match_score, 10) || 0,
  resume_analysis: evalData,
  resume_text: candidate.resume_text,
  resume_filename: candidate.resume_filename
}}];
